package ai.patnub.data.local

import ai.patnub.data.local.entity.KnowledgeChunkEntity
import ai.patnub.data.local.entity.KnowledgeStatus
import ai.patnub.data.local.entity.MedicationReferenceEntity
import android.content.Context
import androidx.core.content.edit
import androidx.room3.withWriteTransaction
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.time.LocalDate

/**
 * Medical reference content shipped in `assets/content/`, generated by `content/build.py`:
 * MedlinePlus health topic summaries and FDA drug label excerpts, copied word for word.
 * It replaces the tables wholesale when the content version changes; patient data is untouched.
 */
object BundledContent {
    private val json = Json { ignoreUnknownKeys = true }

    @Serializable
    private data class Passage(
        val chunk_id: String, val source_id: String, val source_title: String, val publisher: String,
        val version: String, val topic: String, val content_text: String, val source_url: String? = null,
        val reviewed_by: String? = null,
    )

    @Serializable
    private data class Medicine(
        val med_id: String, val name: String, val alias: String? = null, val drug_class: String,
        val strengths: List<String>, val forms: List<String>, val uses: List<String>, val side_effects: List<String>,
        val warnings: List<String>, val storage_text: String, val label_instructions: String,
        val source_citation: String, val source_url: String? = null, val reviewed_by: String? = null,
    )

    @Serializable
    private data class Manifest(val content_version: String)

    fun parseKnowledge(text: String): List<KnowledgeChunkEntity> = json.decodeFromString<List<Passage>>(text).map {
        KnowledgeChunkEntity(
            chunkId = it.chunk_id, sourceId = it.source_id, sourceTitle = it.source_title, publisher = it.publisher,
            version = it.version, reviewDate = LocalDate.parse(it.version), status = KnowledgeStatus.APPROVED,
            topic = it.topic, contentText = it.content_text, sourceUrl = it.source_url, reviewedBy = it.reviewed_by,
        )
    }

    fun parseMedicines(text: String): List<MedicationReferenceEntity> = json.decodeFromString<List<Medicine>>(text).map {
        MedicationReferenceEntity(
            medId = it.med_id, name = it.name, alias = it.alias, drugClass = it.drug_class, strengths = it.strengths,
            forms = it.forms, uses = it.uses, sideEffects = it.side_effects, warnings = it.warnings,
            storageText = it.storage_text, labelInstructions = it.label_instructions,
            sourceCitation = it.source_citation, sourceUrl = it.source_url, reviewedBy = it.reviewed_by,
        )
    }

    /** Loads the bundled content if this database has not got this version yet (or [force]). */
    suspend fun install(context: Context, db: PatnubDatabase, force: Boolean = false) {
        val assets = context.assets
        val read = { name: String -> assets.open("content/$name").bufferedReader().use { it.readText() } }
        val version = json.decodeFromString<Manifest>(read("manifest.json")).content_version
        val prefs = context.getSharedPreferences("content", Context.MODE_PRIVATE)
        if (!force && prefs.getString("version", null) == version) return
        val knowledge = parseKnowledge(read("knowledge.json"))
        val medicines = parseMedicines(read("medicines.json"))
        db.withWriteTransaction {
            db.knowledgeChunkDao().deleteAll()
            db.knowledgeChunkDao().replaceAll(knowledge)
            db.medicationReferenceDao().deleteAll()
            db.medicationReferenceDao().replaceAll(medicines)
        }
        prefs.edit { putString("version", version) }
    }
}
